"use client"

import * as React from "react"
import { ChevronDown } from "lucide-react"

import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover"
import { cn } from "@/lib/utils"
import { useControllableState } from "@/registry/hooks/use-controllable-state"

import { DEFAULT_LABELS } from "./config"
import { RegionPickerPanel } from "./region-picker-panel"
import { regionPickerTriggerVariants } from "./region-picker-parts"
import type { RegionOption, RegionPickerProps } from "./types"
import { createRegionIndex, formatRegionPath } from "./utils"

const EMPTY_PATH: RegionOption[] = []

/** 省市区选择：触发器 + 搜索与分级浏览浮层。数据通过 `regions` 传入，函数形式会惰性加载。 */
function RegionPicker({
  regions,
  value: valueProp,
  defaultValue = null,
  onValueChange,
  depth,
  allowPartial = false,
  name,
  form,
  required = false,
  disabled,
  placeholder,
  fallbackLabel,
  title: titleProp,
  size = "default",
  open: openProp,
  defaultOpen = false,
  onOpenChange,
  labels: labelsProp,
  className,
  ref,
  ...props
}: RegionPickerProps) {
  const labels = { ...DEFAULT_LABELS, ...labelsProp }
  const maxDepth =
    depth === undefined ? Infinity : Math.max(1, Math.floor(depth))

  const triggerRef = React.useRef<HTMLButtonElement>(null)
  React.useImperativeHandle(ref, () => triggerRef.current as HTMLButtonElement)
  const searchRef = React.useRef<HTMLInputElement>(null)
  const proxyRef = React.useRef<HTMLInputElement>(null)

  const [open, setOpen] = useControllableState({
    prop: openProp,
    defaultProp: defaultOpen,
    onChange: onOpenChange,
  })

  // 惰性加载：浮层第一次打开、或已有值需要显示路径时才调用，且只调用一次。
  // 加载函数放进 ref，调用方每次渲染都写内联箭头函数也不会重复请求。
  const [lazyData, setLazyData] = React.useState<RegionOption[] | null>(null)
  const [failed, setFailed] = React.useState(false)
  const [attempt, setAttempt] = React.useState(0)
  const loaderRef = React.useRef(regions)
  const requestRef = React.useRef<Promise<RegionOption[]> | null>(null)
  React.useEffect(() => {
    loaderRef.current = regions
  })

  // 受控与非受控都要拿到当前值，下面的 onChange 里用它反查路径
  const indexRef = React.useRef<ReturnType<typeof createRegionIndex> | null>(
    null,
  )
  const [code, setCode] = useControllableState<string | null>({
    prop: valueProp,
    defaultProp: defaultValue,
    onChange: (next) =>
      onValueChange?.(
        next,
        (next && indexRef.current?.byCode.get(next)) || EMPTY_PATH,
      ),
  })

  const lazy = typeof regions === "function"
  const wantsData = lazy && (open || code !== null)
  React.useEffect(() => {
    if (!wantsData || lazyData) return
    const loader = loaderRef.current
    if (typeof loader !== "function") return
    const request = (requestRef.current ??= loader())
    let stale = false
    request.then(
      (data) => {
        if (!stale) setLazyData(data)
      },
      () => {
        if (!stale) setFailed(true)
      },
    )
    return () => {
      stale = true
    }
  }, [wantsData, lazyData, attempt])

  const retry = () => {
    requestRef.current = null
    setFailed(false)
    setAttempt((count) => count + 1)
  }

  const data = lazy ? lazyData : regions
  // 数据一到就建一次索引（搜索、回显路径都靠它），数据与 depth 不变就不重建
  const index = React.useMemo(
    () => (data ? createRegionIndex(data, { depth: maxDepth }) : null),
    [data, maxDepth],
  )
  React.useEffect(() => {
    indexRef.current = index
  })

  const valuePath = (code !== null && index?.byCode.get(code)) || EMPTY_PATH
  const status = index ? "ready" : failed ? "error" : "loading"

  // 触发器文字：找得到就显示路径；加载中或代码失效时用调用方存的名称兜底
  let text: React.ReactNode = null
  let title: string | undefined
  if (code !== null) {
    if (valuePath.length) {
      title = formatRegionPath(valuePath)
      text = valuePath.map((node, i) => (
        <React.Fragment key={node.code}>
          {i > 0 && <span className="text-muted-foreground/60"> / </span>}
          {node.name}
        </React.Fragment>
      ))
    } else {
      title =
        fallbackLabel ??
        (status === "loading" && lazy
          ? labels.loading
          : `${labels.unknown}（${code}）`)
      text = title
    }
  }

  const commit = (path: RegionOption[]) => {
    setCode(path.length ? path[path.length - 1].code : null)
    setOpen(false)
  }

  // 表单：同名的隐藏输入负责提交代码；它是可校验的文本输入，所以 required 能拦住提交、
  // 浏览器的气泡提示也有地方挂。覆盖在触发器上，聚焦时转交给触发器。
  React.useEffect(() => {
    proxyRef.current?.setCustomValidity(
      required && code === null ? labels.required : "",
    )
  }, [required, code, labels.required])

  // 非受控的表单重置回到初始值；reset 事件在表单清空之前触发，等一帧再覆盖
  const controlled = valueProp !== undefined
  React.useEffect(() => {
    const element = proxyRef.current?.form
    if (!element || controlled) return
    const reset = () => window.setTimeout(() => setCode(defaultValue))
    element.addEventListener("reset", reset)
    return () => element.removeEventListener("reset", reset)
  }, [controlled, defaultValue, setCode])

  return (
    <div
      data-slot="region-picker"
      data-size={size}
      data-disabled={disabled ? "" : undefined}
      className={cn("relative w-full", className)}
    >
      <Popover open={open} onOpenChange={(next) => setOpen(next)}>
        <PopoverTrigger
          {...props}
          ref={triggerRef}
          data-slot="region-picker-trigger"
          disabled={disabled}
          title={title ?? titleProp}
          aria-busy={
            code !== null && !index && !failed && lazy ? true : undefined
          }
          className={regionPickerTriggerVariants({ size })}
        >
          <span
            data-slot="region-picker-value-text"
            className={cn(
              "min-w-0 flex-1 truncate",
              code === null && "text-muted-foreground",
            )}
          >
            {code === null ? (placeholder ?? labels.placeholder) : text}
          </span>
          <ChevronDown
            aria-hidden="true"
            className="size-4 shrink-0 text-muted-foreground"
          />
        </PopoverTrigger>
        <PopoverContent
          align="start"
          className="w-[26rem] max-w-[calc(100vw-1rem)] min-w-(--anchor-width) gap-0"
          // 触屏上不自动聚焦搜索框，免得弹出软键盘盖住列表
          initialFocus={(type) => (type === "touch" ? true : searchRef.current)}
        >
          <RegionPickerPanel
            index={index}
            status={status}
            labels={labels}
            value={code}
            valuePath={valuePath}
            depth={maxDepth}
            allowPartial={allowPartial}
            required={required}
            inputRef={searchRef}
            onRetry={retry}
            onCommit={commit}
          />
        </PopoverContent>
      </Popover>
      <input
        ref={proxyRef}
        data-slot="region-picker-value"
        tabIndex={-1}
        aria-hidden="true"
        autoComplete="off"
        name={name}
        form={form}
        required={required}
        disabled={disabled}
        value={code ?? ""}
        onChange={() => {}}
        onFocus={() => triggerRef.current?.focus()}
        className="pointer-events-none absolute inset-0 size-full opacity-0"
      />
    </div>
  )
}

export { RegionPicker, regionPickerTriggerVariants }
export type {
  RegionOption,
  RegionPickerProps,
  RegionPickerSize,
  RegionsSource,
} from "./types"

"use client"

import * as React from "react"
import { Check, Search } from "lucide-react"

import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { cn } from "@/lib/utils"

import type { RegionPickerLabels } from "./config"
import {
  RegionPickerHighlight,
  RegionPickerLevels,
  RegionPickerNotice,
  RegionPickerOption,
} from "./region-picker-parts"
import type { RegionOption } from "./types"
import {
  formatRegionPath,
  isLeafRegion,
  searchRegionIndex,
  type RegionHighlight,
  type RegionIndex,
} from "./utils"

type Row = {
  node: RegionOption
  /** 从 0 数的层级 */
  level: number
  /** 从最顶层到该节点 */
  path: RegionOption[]
  highlights?: (RegionHighlight | null)[]
}

const EMPTY_PATH: RegionOption[] = []

const fill = (template: string, values: Record<string, string | number>) =>
  template.replace(/\{(\w+)\}/g, (_, key) => String(values[key] ?? ""))

/**
 * 浮层内容：搜索框 + 层级标签条 + 当前层级的选项（或搜索结果）。
 * 浮层关闭时整体卸载，所以浏览位置、搜索词每次打开都是全新的。
 */
function RegionPickerPanel({
  index,
  status,
  labels,
  value,
  valuePath,
  depth,
  allowPartial,
  required,
  inputRef,
  onRetry,
  onCommit,
}: {
  /** 数据没加载好时为 null */
  index: RegionIndex | null
  status: "loading" | "error" | "ready"
  labels: RegionPickerLabels
  value: string | null
  valuePath: RegionOption[]
  depth: number
  allowPartial: boolean
  required: boolean
  inputRef: React.RefObject<HTMLInputElement | null>
  onRetry: () => void
  /** 确认选择；空数组表示清除 */
  onCommit: (path: RegionOption[]) => void
}) {
  const baseId = React.useId()
  const listId = `${baseId}-list`
  const listRef = React.useRef<HTMLDivElement>(null)

  const [query, setQuery] = React.useState("")
  // null = 还没手动浏览过，跟随当前值所在的层级；这样懒加载的数据到了之后也能自动定位
  const [trailState, setTrailState] = React.useState<RegionOption[] | null>(
    null,
  )

  const defaultTrail = React.useMemo(
    () =>
      valuePath.slice(
        0,
        Math.max(0, Math.min(valuePath.length - 1, depth - 1)),
      ),
    [valuePath, depth],
  )
  const trail = trailState ?? defaultTrail
  const level = trail.length
  const roots = index?.roots ?? EMPTY_PATH
  const options = trail.length
    ? (trail[level - 1].children ?? EMPTY_PATH)
    : roots

  // 当前层级里属于已选路径的那一项（上级路径一致时才算）
  const selectedHere =
    valuePath.length > level &&
    trail.every((node, i) => node.code === valuePath[i].code)
      ? valuePath[level]
      : undefined

  const searching = query.trim() !== ""
  const search = React.useMemo(
    () => (index && searching ? searchRegionIndex(index, query) : null),
    [index, query, searching],
  )

  const rows = React.useMemo<Row[]>(() => {
    if (search)
      return search.results.map(({ node, level, path, highlights }) => ({
        node,
        level,
        path,
        highlights,
      }))
    return options.map((node) => ({
      node,
      level,
      path: [...trail, node],
    }))
  }, [search, options, trail, level])

  // 列表一换（进入下级、搜索词变化），高亮项回到已选项或第一项
  const listKey = searching
    ? `s:${query}`
    : `b:${trail.map((node) => node.code).join(",")}`
  const selectedCode = searching ? value : selectedHere?.code
  const selectedAt = rows.findIndex((row) => row.node.code === selectedCode)
  const fallbackActive = rows.length ? Math.max(0, selectedAt) : -1
  const [activeState, setActiveState] = React.useState({
    key: listKey,
    index: fallbackActive,
  })
  const active = Math.min(
    activeState.key === listKey ? activeState.index : fallbackActive,
    rows.length - 1,
  )
  const setActive = (next: number) =>
    setActiveState({ key: listKey, index: next })
  const activeId = active >= 0 ? `${baseId}-opt-${active}` : undefined

  // 键盘移动后把高亮项滚进视野；打开时也会把已选项滚出来
  React.useEffect(() => {
    if (!activeId) return
    document.getElementById(activeId)?.scrollIntoView({ block: "nearest" })
  }, [activeId, listKey])

  const choose = (row: Row) => {
    if (isLeafRegion(row.node, row.level, depth)) return onCommit(row.path)
    setTrailState(row.path)
    setQuery("")
    inputRef.current?.focus()
  }

  const goUp = (to: number) => {
    setTrailState(trail.slice(0, to))
    setQuery("")
    inputRef.current?.focus()
  }

  const columns = () => {
    const template = listRef.current
      ? getComputedStyle(listRef.current).gridTemplateColumns
      : ""
    return Math.max(1, template.split(" ").filter(Boolean).length)
  }

  const onKeyDown = (event: React.KeyboardEvent<HTMLInputElement>) => {
    // 拼音输入法组词时的方向键、回车是在选候选词，不能当作列表操作
    if (event.nativeEvent.isComposing) return
    const count = rows.length
    const cols = columns()
    switch (event.key) {
      case "ArrowDown": {
        if (!count) return
        event.preventDefault()
        const next = active + cols
        if (next < count) setActive(next)
        // 最后一行不满时，从倒数第二行往下落到最后一项
        else if (Math.floor(active / cols) < Math.floor((count - 1) / cols))
          setActive(count - 1)
        return
      }
      case "ArrowUp":
        if (!count) return
        event.preventDefault()
        if (active - cols >= 0) setActive(active - cols)
        return
      // 左右键平时是移动光标，搜索框为空且是多列网格时才用来横向移动
      case "ArrowRight":
        if (!count || query || cols < 2) return
        event.preventDefault()
        setActive(Math.min(count - 1, active + 1))
        return
      case "ArrowLeft":
        if (!count || query || cols < 2) return
        event.preventDefault()
        setActive(Math.max(0, active - 1))
        return
      case "Enter":
        event.preventDefault()
        if (active >= 0) choose(rows[active])
        return
      case "Backspace":
        if (!query && trail.length) {
          event.preventDefault()
          goUp(trail.length - 1)
        }
        return
    }
  }

  const ready = status === "ready" && index !== null
  const announcement = !ready
    ? status === "error"
      ? labels.loadFailed
      : labels.loading
    : searching
      ? search && search.total
        ? fill(labels.resultStatus, { count: search.total })
        : labels.empty
      : fill(labels.levelStatus, { level: level + 1, count: rows.length })

  const showConfirm = allowPartial && !searching && ready && trail.length > 0
  const showClear = value !== null && !required

  return (
    <div data-slot="region-picker-panel" className="flex flex-col gap-2.5">
      <div className="relative">
        <Search
          aria-hidden="true"
          className="pointer-events-none absolute top-1/2 left-2.5 size-3.5 -translate-y-1/2 text-muted-foreground"
        />
        <Input
          ref={inputRef}
          data-slot="region-picker-search"
          role="combobox"
          aria-label={labels.searchLabel}
          aria-expanded="true"
          aria-autocomplete="list"
          aria-controls={ready && rows.length ? listId : undefined}
          aria-activedescendant={ready ? activeId : undefined}
          autoComplete="off"
          autoCapitalize="off"
          spellCheck={false}
          placeholder={labels.searchPlaceholder}
          className="pl-8"
          value={query}
          onChange={(event) => setQuery(event.target.value)}
          onKeyDown={onKeyDown}
        />
      </div>

      {ready && !searching && (
        <RegionPickerLevels
          trail={trail}
          currentLabel={selectedHere?.name}
          pendingLabel={labels.levelPending}
          ariaLabel={labels.levelNav}
          onSelect={goUp}
        />
      )}

      {!ready ? (
        status === "error" ? (
          <RegionPickerNotice>
            <span>{labels.loadFailed}</span>
            <Button type="button" variant="outline" size="sm" onClick={onRetry}>
              {labels.retry}
            </Button>
          </RegionPickerNotice>
        ) : (
          <RegionPickerNotice loading>{labels.loading}</RegionPickerNotice>
        )
      ) : rows.length ? (
        <div
          ref={listRef}
          id={listId}
          role="listbox"
          aria-label={labels.searchLabel}
          data-slot="region-picker-list"
          className={cn(
            "max-h-60 overflow-y-auto overscroll-contain",
            searching
              ? "flex flex-col gap-0.5"
              : "grid grid-cols-[repeat(auto-fill,minmax(7rem,1fr))] gap-1",
          )}
        >
          {rows.map((row, i) => {
            const leaf = isLeafRegion(row.node, row.level, depth)
            const selected = row.node.code === selectedCode
            return (
              <RegionPickerOption
                key={row.path.map((node) => node.code).join("/")}
                id={`${baseId}-opt-${i}`}
                title={formatRegionPath(row.path)}
                active={i === active}
                selected={selected}
                branch={!leaf}
                onSelect={() => choose(row)}
                onHover={() => i !== active && setActive(i)}
              >
                {searching ? (
                  <>
                    <span className="min-w-0 flex-1 truncate">
                      {row.path.map((node, at) => (
                        <React.Fragment key={node.code}>
                          {at > 0 && (
                            <span className="text-muted-foreground/60">
                              {" / "}
                            </span>
                          )}
                          <span
                            className={cn(
                              at < row.level && "text-muted-foreground",
                            )}
                          >
                            <RegionPickerHighlight
                              text={node.name}
                              range={row.highlights?.[at]?.name}
                            />
                          </span>
                        </React.Fragment>
                      ))}
                    </span>
                    <span className="shrink-0 text-xs text-muted-foreground tabular-nums">
                      <RegionPickerHighlight
                        text={row.node.code}
                        range={row.highlights?.[row.level]?.code}
                      />
                    </span>
                  </>
                ) : (
                  <span className="truncate">{row.node.name}</span>
                )}
                {selected && leaf && (
                  <Check
                    aria-hidden="true"
                    className="ml-auto size-3.5 shrink-0"
                  />
                )}
              </RegionPickerOption>
            )
          })}
        </div>
      ) : (
        <RegionPickerNotice>{labels.empty}</RegionPickerNotice>
      )}

      {search && search.total > search.results.length && (
        <p
          data-slot="region-picker-hint"
          className="px-1 text-xs text-muted-foreground"
        >
          {fill(labels.resultTruncated, { limit: search.results.length })}
        </p>
      )}

      {(showConfirm || showClear) && (
        <div
          data-slot="region-picker-footer"
          className="flex items-center gap-2 border-t border-border pt-2.5"
        >
          {showConfirm && (
            <Button
              type="button"
              size="sm"
              className="min-w-0"
              onClick={() => onCommit(trail)}
            >
              <span className="truncate">
                {fill(labels.confirmPartial, { name: formatRegionPath(trail) })}
              </span>
            </Button>
          )}
          {showClear && (
            <Button
              type="button"
              variant="ghost"
              size="sm"
              className="ml-auto shrink-0"
              onClick={() => onCommit(EMPTY_PATH)}
            >
              {labels.clear}
            </Button>
          )}
        </div>
      )}

      <span role="status" className="sr-only">
        {announcement}
      </span>
    </div>
  )
}

export { RegionPickerPanel }

import * as React from "react"
import { cva } from "class-variance-authority"
import { ChevronRight, Loader2 } from "lucide-react"

import { Button } from "@/components/ui/button"
import { cn } from "@/lib/utils"

import type { RegionOption } from "./types"

/** 触发器外观与 shadcn Input 同一套，高度只用既有三档：28 / 32 / 36px */
const regionPickerTriggerVariants = cva(
  "flex w-full min-w-0 items-center gap-2 rounded-lg border border-input bg-transparent text-left transition-colors outline-none focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50 disabled:pointer-events-none disabled:cursor-not-allowed disabled:bg-input/50 disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-3 aria-invalid:ring-destructive/20 data-popup-open:border-ring data-popup-open:ring-3 data-popup-open:ring-ring/50 dark:bg-input/30 dark:disabled:bg-input/80 dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40",
  {
    variants: {
      size: {
        sm: "h-7 px-2 text-base md:text-sm",
        default: "h-8 px-2.5 text-base md:text-sm",
        lg: "h-9 px-3 text-base",
      },
    },
    defaultVariants: { size: "default" },
  },
)

/** 按区间高亮一段文字，区间为空时原样输出 */
function RegionPickerHighlight({
  text,
  range,
}: {
  text: string
  range?: [number, number]
}) {
  if (!range || range[0] >= range[1]) return text
  return (
    <>
      {text.slice(0, range[0])}
      <mark
        data-slot="region-picker-mark"
        className="rounded-xs bg-primary/15 px-px text-foreground"
      >
        {text.slice(range[0], range[1])}
      </mark>
      {text.slice(range[1])}
    </>
  )
}

/** 层级标签条：已选的层级显示名称，当前层级显示占位，点击可回到该层 */
function RegionPickerLevels({
  trail,
  currentLabel,
  pendingLabel,
  ariaLabel,
  onSelect,
}: {
  /** 已经确定的上级，从最顶层开始 */
  trail: RegionOption[]
  /** 当前层级已选中的名称，没有则显示占位 */
  currentLabel?: string
  pendingLabel: string
  ariaLabel: string
  /** 回到第 `level` 层（0 = 最顶层） */
  onSelect: (level: number) => void
}) {
  return (
    <nav
      data-slot="region-picker-levels"
      aria-label={ariaLabel}
      className="-mx-0.5 flex gap-1 overflow-x-auto px-0.5 py-0.5"
    >
      {trail.map((node, level) => (
        <Button
          key={node.code}
          type="button"
          variant="ghost"
          size="sm"
          data-slot="region-picker-level"
          title={node.name}
          className="max-w-[8rem] shrink-0 justify-start"
          onClick={() => onSelect(level)}
        >
          <span className="truncate">{node.name}</span>
        </Button>
      ))}
      <Button
        type="button"
        variant="secondary"
        size="sm"
        data-slot="region-picker-level"
        data-current=""
        aria-current="step"
        title={currentLabel}
        className="max-w-[8rem] shrink-0 justify-start"
        // 当前层级点了没有动作，保持可聚焦让读屏能读到 aria-current
        onClick={() => onSelect(trail.length)}
      >
        <span
          className={cn("truncate", !currentLabel && "text-muted-foreground")}
        >
          {currentLabel ?? pendingLabel}
        </span>
      </Button>
    </nav>
  )
}

