type RegionPickerSize = "sm" | "default" | "lg"

type RegionPickerProps = Omit<
  React.ComponentProps<"button">,
  | "value"
  | "defaultValue"
  | "onChange"
  | "type"
  | "name"
  | "form"
  | "children"
  | "placeholder"
> & {
  /**
   * 地区数据。传数组直接使用（请保持引用稳定）；
